export function nextGeneration(cells: Cell[]): Cell[] {
  const key = (x: number, y: number) => `${x},${y}`;
  const live = new Set(cells.map(([x, y]) => key(x, y)));

  // Count live neighbours for every cell that could possibly be alive next
  // generation: every live cell and every neighbour of a live cell.
  const neighbourCounts = new Map<string, number>();
  for (const [x, y] of cells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const k = key(x + dx, y + dy);
        neighbourCounts.set(k, (neighbourCounts.get(k) ?? 0) + 1);
      }
    }
  }

  const next: Cell[] = [];
  for (const [k, count] of neighbourCounts) {
    const isAlive = live.has(k);
    if (count === 3 || (isAlive && count === 2)) {
      const [xs, ys] = k.split(",");
      next.push([Number(xs), Number(ys)]);
    }
  }

