  const live = new Set(cells.map(([x, y]) => key(x, y)));

  // Count live neighbours for every cell that could possibly be alive next
  // generation: every live cell and every neighbour of a live cell.
  const neighbourCounts = new Map<string, number>();
  for (const [x, y] of cells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
